contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry performing the property-based check
    function run(address caller, address newOwner) public payable {
        // Precondition: caller must be a non-zero address to be meaningful
        require(caller != address(0));

        // Read owner before the change
        address ownerBefore = c.owner();

        // We will attempt to call transferOwnership as if msg.sender == caller.
        // Since the checker runs this contract as msg.sender when calling c, we simulate
        // calling from 'caller' by using a low-level call to c from this contract
        // only when caller equals address(this) will the call be made directly (normal case).
        // To allow arbitrary caller parameter to influence behavior according to the property,
        // we branch to perform the call only when caller == address(this); otherwise we
        // perform the call but it will have msg.sender == address(this) (not equal to caller)
        // The key observable is whether the call reverted and the resulting owner.

        bool reverted;
        // Perform the call: try-catch to detect revert. The call is always performed from this contract.
        // The property will relate the revert outcome to whether ownerBefore == address(this) (the actual sender).
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address ownerAfter = c.owner();

        // General rule: If the call did not revert then ownerAfter equals newOwner.
        // If the call reverted then ownerAfter equals ownerBefore (no state change on revert).
        // Also, since onlyOwner requires msg.sender == owner, a successful call implies
        // that this contract was the owner before the call.
        assert((!reverted && ownerAfter == newOwner && ownerBefore == address(this)) || (reverted && ownerAfter == ownerBefore));
    }

    // receive to accept ETH if needed (not used here but present per template allowance)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing the property-based check
    // Parameters: addrSetupOwner is the address we set as owner via transferOwnership (must be non-zero)
    //             callSenderIsOwner: if true, the test will first make this contract the owner so that
    //                                its subsequent call to owned() will have msg.sender == owner.
    function run(address addrSetupOwner, bool callSenderIsOwner) public payable {
        require(addrSetupOwner != address(0));

        // Read initial observations
        address ownerBefore = c.owner();
        uint balanceBefore = address(c).balance;

        // If requested, make this contract the owner by calling transferOwnership from the current owner.
        // Only perform the transferOwnership call if the current owner equals address(this) so it succeeds;
        // otherwise we attempt it and observe revert via try/catch. This sets up scenarios where this contract
        // is owner or is not owner depending on c's initial state and the parameter.
        bool transferReverted = false;
        if (callSenderIsOwner) {
            // Only attempt to change ownership if the existing owner equals address(this); if not, this will revert.
            // We still perform the call to observe revert behavior; this call must be top-level.
            try c.transferOwnership(addrSetupOwner) {
                transferReverted = false;
            } catch {
                transferReverted = true;
            }
        }

        // After possible transfer, read current owner
        address ownerAfterSetup = c.owner();
        uint balanceAfterSetup = address(c).balance;

        // Now attempt to call owned() and observe whether it reverts. The invocation is top-level and may revert.
        bool ownedReverted;
        try c.owned() {
            ownedReverted = false;
        } catch {
            ownedReverted = true;
        }

        // Read owner and balance after the owned() call
        address ownerFinal = c.owner();
        uint balanceFinal = address(c).balance;

        // General rule asserted for all inputs and observable behavior:
        // 1) The owned() call must succeed (not revert) only when msg.sender equals the contract's owner at the time of the call.
        //    Since calls from this test execute with msg.sender == address(this), this means: ownedReverted == (ownerAfterSetup != address(this)).
        // 2) Calling owned() does not change the public owner() value nor the contract balance.
        assert(
            (ownedReverted == (ownerAfterSetup != address(this)))
            && ownerFinal == ownerAfterSetup
            && balanceFinal == balanceAfterSetup
        );
    }

    receive() external payable {}
}

