    // then attempt a transfer and observe behavior. We take a candidate newOwner and a boolean tryMakeOwner
    // which, when true, first sets owner to this contract by calling c.transferOwnership(address(this)).

    function run(address candidateNewOwner, bool makeThisOwner) public payable {
        require(candidateNewOwner != address(0));

        // Read initial owner
        address ownerBefore = c.owner();

        // If requested, try to make this contract the owner by calling transferOwnership from this contract.
        // That call will succeed only if ownerBefore == address(this). If it reverts, catch and continue.
        bool setupReverted;
        if (makeThisOwner) {
            // must attempt and record revert without aborting test
            try c.transferOwnership(address(this)) {
                setupReverted = false;
            } catch {
                setupReverted = true;
            }
        } else {
            setupReverted = false;
        }

        // Read owner after optional setup
        address ownerAfterSetup = c.owner();

        // Now attempt the main transferOwnership to candidateNewOwner and record whether it reverted
        bool mainReverted;
        try c.transferOwnership(candidateNewOwner) {
            mainReverted = false;
        } catch {
            mainReverted = true;
        }

        // Read final owner
        address ownerFinal = c.owner();

        // General rule:
        // - If the main call did not revert, then ownerFinal == candidateNewOwner.
        // - If the main call reverted, then ownerFinal == ownerAfterSetup (state unchanged by the failed call).
        // Additionally, the main call succeeds only when msg.sender == ownerAfterSetup (onlyOwner enforced).
        // Since msg.sender for calls to c is this contract, that means: mainReverted == (address(this) != ownerAfterSetup).

        assert(
            (!mainReverted && ownerFinal == candidateNewOwner) ||
